const STORYBOOK_MCP_ADDON = '@storybook/addon-mcp';
const DEFAULT_MCP_ENDPOINT = '/mcp';
const ONE_DAY_MS = 24 * 60 * 60 * 1000;
const SEVEN_DAYS_MS = 7 * ONE_DAY_MS;

export type RuntimeInstanceRecord = {
  schemaVersion: 1;
  instanceId: string;
  pid: number;
  cwd: string;
  url: string;
  port: number;
  agent?: string;
  storybookVersion: string;
  startedAt: string;
  updatedAt: string;
